import{_ as t,o as a,c as i,ae as o}from"./chunks/framework.BCZ_EjGL.js";const u=JSON.parse('{"title":"Lifecycle Overview","description":"","frontmatter":{},"headers":[],"relativePath":"v1.0.0/guide/lifecycle.md","filePath":"v1.0.0/guide/lifecycle.md"}'),n={name:"v1.0.0/guide/lifecycle.md"};function r(s,e,l,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="lifecycle-overview" tabindex="-1">Lifecycle Overview <a class="header-anchor" href="#lifecycle-overview" aria-label="Permalink to &quot;Lifecycle Overview&quot;">​</a></h1><p>Lifecycle events are the primary way your SAP Analytics Cloud dashboard interacts with the AskBot AI widget. They allow you to respond to user messages, form submissions, and UI state changes.</p><h2 id="how-to-use-events" tabindex="-1">How to use Events <a class="header-anchor" href="#how-to-use-events" aria-label="Permalink to &quot;How to use Events&quot;">​</a></h2><p>In SAP Analytics Cloud, you don&#39;t typically assign functions to properties like <code>AskBotAI.onReady = function</code>. Instead, the widget triggers these events which you can then capture in your dashboard&#39;s scripting environment.</p><p>The documentation for each event provides a <strong>Practical Example</strong> showing how to use the available API methods to process the event data.</p><hr><h2 id="event-categories" tabindex="-1">Event Categories <a class="header-anchor" href="#event-categories" aria-label="Permalink to &quot;Event Categories&quot;">​</a></h2><h3 id="initialization-state" tabindex="-1">Initialization &amp; State <a class="header-anchor" href="#initialization-state" aria-label="Permalink to &quot;Initialization &amp; State&quot;">​</a></h3><ul><li><a href="./../api/event-onInitialization"><strong>onInitialization</strong></a>: Triggered when the bot is ready for interaction.</li><li><a href="./../api/event-onChatOpened"><strong>onChatOpened</strong></a>: Triggered when the chat window is expanded.</li><li><a href="./../api/event-onChatClosed"><strong>onChatClosed</strong></a>: Triggered when the chat window is collapsed.</li></ul><h3 id="user-interaction" tabindex="-1">User Interaction <a class="header-anchor" href="#user-interaction" aria-label="Permalink to &quot;User Interaction&quot;">​</a></h3><ul><li><a href="./../api/event-onActionClicked"><strong>onActionClicked</strong></a>: Handle &quot;Plain&quot; button clicks for custom navigation.</li><li><a href="./../api/event-onFormSubmitted"><strong>onFormSubmitted</strong></a>: Capture structured data from interactive forms.</li><li><a href="./../api/event-onQuickQuestionClicked"><strong>onQuickQuestionClicked</strong></a>: Respond to suggestion chip clicks.</li></ul><h3 id="messaging-ai" tabindex="-1">Messaging &amp; AI <a class="header-anchor" href="#messaging-ai" aria-label="Permalink to &quot;Messaging &amp; AI&quot;">​</a></h3><ul><li><a href="./../api/event-onMessageSent"><strong>onMessageSent</strong></a>: Monitor outgoing user messages (retrieves last message text).</li><li><a href="./../api/event-onMessageReceived"><strong>onMessageReceived</strong></a>: Monitor incoming bot replies (retrieves last reply text).</li><li><a href="./../api/event-mic-controls"><strong>Voice Events</strong></a>: Track microphone usage (STT).</li></ul>',13)])])}const p=t(n,[["render",r]]);export{u as __pageData,p as default};
